from AlgorithmImports import *
from datetime import timedelta


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(-100, 100, timedelta(0), timedelta(365))

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_crossover = False
        self.no_entry_today = False
        self.last_session_date = None

        self.held_contract = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_price = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        if bar.Symbol != self.spy:
            return

        prior_fast = self.fast.Current.Value if self.fast.IsReady else None
        prior_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if prior_fast is None or prior_slow is None:
            return

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        bar_time = bar.EndTime.time()
        eligible_time = (
            bar_time >= self.TimeRules.At(9, 45).time() and
            bar_time <= self.TimeRules.At(14, 30).time()
        )

        if eligible_time and prior_fast <= prior_slow and self.fast.Current.Value > self.slow.Current.Value:
            self.pending_crossover = True

    def OnData(self, slice):
        today = self.Time.date()
        if self.last_session_date != today:
            self.last_session_date = today
            self.no_entry_today = False

        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationSafety()
        self.HandleExit(slice)

        if self.pending_crossover:
            self.pending_crossover = False
            self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.no_entry_today:
            return

        if self.held_contract is not None or self.entry_order_id is not None:
            return

        if self.Portfolio[self.spy].Invested:
            return

        if self.Time.time() < self.TimeRules.At(9, 45).time() or self.Time.time() > self.TimeRules.At(14, 30).time():
            return

        if not slice.OptionChains:
            self.Debug(f"{self.Time}: skipped entry; no option chain.")
            return

        chain = None
        for symbol, candidate in slice.OptionChains.items():
            if symbol == self.option.Symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug(f"{self.Time}: skipped entry; SPY option chain unavailable.")
            return

        spot = self.Securities[self.spy].Price
        if spot <= 0:
            self.Debug(f"{self.Time}: skipped entry; invalid SPY price.")
            return

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call and contract.Expiry.date() > today
        })

        if not expirations:
            self.Debug(f"{self.Time}: skipped entry; no valid call expiration.")
            return

        # Select the nearest available non-expired calendar-date expiration.
        expiry = expirations[0]
        dte = (expiry - today).days

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiry
            and contract.Strike >= spot * 1.01
        ]

        if not candidates:
            self.Debug(f"{self.Time}: skipped entry; no call >= 101% SPY for {expiry}.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_order_id = self.MarketOrder(selected.Symbol, 1).OrderId
        self.Debug(
            f"{self.Time}: entry submitted {selected.Symbol}, "
            f"strike {selected.Strike}, expiry {expiry}, DTE {dte}."
        )

    def HandleExit(self, slice):
        if self.held_contract is None:
            return

        holding = self.Portfolio[self.held_contract]
        if not holding.Invested:
            return

        contract = None
        for chain in slice.OptionChains.values():
            for candidate in chain:
                if candidate.Symbol == self.held_contract:
                    contract = candidate
                    break
            if contract is not None:
                break

        if contract is not None and self.entry_price is not None and self.entry_price > 0:
            bid = contract.BidPrice
            ask = contract.AskPrice
            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                if midpoint >= self.entry_price * 1.50:
                    self.SubmitExit("profit target")
                    return

        expiry = self.held_contract.ID.Date.date()
        prior_trading_day = self.PreviousTradingDay(expiry)
        if today_equals(self.Time.date(), prior_trading_day) and self.Time.time() >= self.TimeRules.At(15, 45).time():
            self.SubmitExit("15:45 pre-expiration time stop")

    def HandleExpirationSafety(self):
        if self.held_contract is None:
            return

        holding = self.Portfolio[self.held_contract]
        if not holding.Invested:
            return

        expiry = self.held_contract.ID.Date.date()
        if self.Time.date() >= expiry:
            self.no_entry_today = True
            self.SubmitExit("expiration safety")

    def HandleUnexpectedSpyPosition(self):
        if self.Portfolio[self.spy].Invested:
            self.Debug(f"{self.Time}: unexpected SPY exercise/assignment position; liquidating.")
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)

    def SubmitExit(self, reason):
        if self.held_contract is None or self.exit_order_id is not None:
            return

        for ticket in self.Transactions.GetOpenOrderTickets(self.held_contract):
            ticket.Cancel("Replacing open exit order.")

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        self.exit_order_id = self.MarketOrder(self.held_contract, -quantity).OrderId
        self.Debug(f"{self.Time}: exit submitted for {self.held_contract}; {reason}.")

    def OnOrderEvent(self, order_event):
        if order_event.Status != OrderStatus.Filled:
            return

        if order_event.OrderId == self.entry_order_id:
            self.held_contract = order_event.Symbol
            self.entry_price = order_event.FillPrice
            self.entry_order_id = None
            self.Debug(
                f"{self.Time}: entry filled {self.held_contract} at {self.entry_price:.2f}."
            )
            return

        if order_event.OrderId == self.exit_order_id:
            self.Debug(
                f"{self.Time}: exit filled {order_event.Symbol} at {order_event.FillPrice:.2f}."
            )
            self.exit_order_id = None
            self.held_contract = None
            self.entry_price = None

    def PreviousTradingDay(self, expiry):
        candidate = expiry - timedelta(days=1)
        while candidate.weekday() >= 5:
            candidate -= timedelta(days=1)
        return candidate


def today_equals(left, right):
    return left == right

