from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def initialize(self):
        self.set_time_zone(TimeZones.NEW_YORK)
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)

        self.spy = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        ).symbol

        self.option_symbol = self.add_option("SPY", Resolution.MINUTE).symbol
        self.option_symbol.set_filter(
            lambda universe: universe.include_weeklys()
            .strikes(-200, 200)
            .expiration(0, 1000)
        )

        self._closes = deque(maxlen=20)
        self._previous_fast = None
        self._previous_slow = None
        self._current_slice = None

        self._held_contract = None
        self._held_expiry = None
        self._entry_price = None
        self._entry_order_id = None
        self._exit_order_id = None
        self._no_entries_date = None

        self._five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self._five_minute_consolidator.data_consolidated += self._on_five_minute_bar

    def on_data(self, slice: Slice):
        self._current_slice = slice

        if self.portfolio[self.spy].invested:
            self.debug("Unexpected SPY exercise/assignment position; liquidating.")
            self.market_order(self.spy, -self.portfolio[self.spy].quantity)

        self._handle_expiration_protection()
        self._handle_option_exit(slice)

        spy_bar = slice.bars.get(self.spy)
        if spy_bar is not None:
            self._five_minute_consolidator.update(spy_bar)

    def _on_five_minute_bar(self, bar: TradeBar):
        self._closes.append(bar.close)

        if len(self._closes) < 20:
            return

        fast = sum(list(self._closes)[-5:]) / 5.0
        slow = sum(self._closes) / 20.0

        bullish_cross = (
            self._previous_fast is not None
            and self._previous_slow is not None
            and self._previous_fast <= self._previous_slow
            and fast > slow
        )

        self._previous_fast = fast
        self._previous_slow = slow

        end_time = bar.end_time
        if not bullish_cross:
            return

        if not (end_time.hour > 9 or (end_time.hour == 9 and end_time.minute >= 45)):
            return
        if not (end_time.hour < 14 or (end_time.hour == 14 and end_time.minute <= 30)):
            return

        self._try_enter_call(bar.close)

    def _try_enter_call(self, spy_price: float):
        if self._no_entries_date == self.time.date():
            return

        if self._held_contract is not None and self.portfolio[self._held_contract].invested:
            return

        if self._entry_order_id is not None:
            return

        chain = self._current_slice.option_chains.get(self.option_symbol)
        if chain is None:
            self.debug("Entry skipped: no SPY option chain in current Slice.")
            return

        today = self.time.date()
        expirations = sorted({
            contract.expiry.date()
            for contract in chain
            if contract.right == OptionRight.CALL and contract.expiry.date() > today
        })

        if not expirations:
            self.debug("Entry skipped: no eligible call expiration.")
            return

        # Use the nearest non-expired listed expiration. DTE is calendar-date based.
        expiry = expirations[0]
        dte = (expiry - today).days
        if dte <= 0:
            self.debug("Entry skipped: expiration does not have positive calendar DTE.")
            return

        minimum_strike = 1.01 * spy_price
        candidates = [
            contract for contract in chain
            if contract.right == OptionRight.CALL
            and contract.expiry.date() == expiry
            and contract.strike >= minimum_strike
        ]

        if not candidates:
            self.debug("Entry skipped: no qualifying call strike.")
            return

        contract = min(candidates, key=lambda c: (c.strike, str(c.symbol)))
        ticket = self.market_order(contract.symbol, 1)

        if ticket is None or ticket.order_id <= 0:
            self.debug("Entry skipped: market order submission failed.")
            return

        self._entry_order_id = ticket.order_id
        self._held_contract = contract.symbol
        self._held_expiry = contract.expiry.date()
        self._entry_price = None
        self.debug(f"Entry submitted: {contract.symbol}.")

    def _handle_option_exit(self, slice: Slice):
        if self._held_contract is None or not self.portfolio[self._held_contract].invested:
            return

        if self._exit_order_id is not None:
            return

        if self._held_expiry is not None:
            previous_trading_day = self.securities[self.spy].exchange.hours.get_previous_trading_day(
                self._held_expiry
            )
            if self.time.date() == previous_trading_day and self.time.hour == 15 and self.time.minute == 45:
                self._submit_exit("time stop")
                return

        if self._entry_price is None or self._entry_price <= 0:
            return

        quote = slice.quote_bars.get(self._held_contract)
        if quote is None or quote.bid is None or quote.ask is None:
            return

        bid = quote.bid.close
        ask = quote.ask.close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self._entry_price:
            self._submit_exit("profit target")

    def _handle_expiration_protection(self):
        if (
            self._held_contract is None
            or self._held_expiry is None
            or not self.portfolio[self._held_contract].invested
        ):
            return

        if self.time.date() >= self._held_expiry:
            self._no_entries_date = self.time.date()
            self.debug("Expiration protection triggered; liquidating option.")
            if self._exit_order_id is None:
                self._submit_exit("expiration protection")

    def _submit_exit(self, reason: str):
        if self._held_contract is None:
            return

        if self._exit_order_id is not None:
            ticket = self.transactions.get_order_ticket(self._exit_order_id)
            if ticket is not None:
                ticket.cancel("Replacing open exit order.")
            self._exit_order_id = None

        quantity = self.portfolio[self._held_contract].quantity
        if quantity == 0:
            return

        ticket = self.market_order(self._held_contract, -quantity)
        if ticket is not None and ticket.order_id > 0:
            self._exit_order_id = ticket.order_id
            self.debug(f"Exit submitted ({reason}): {self._held_contract}.")

    def on_order_event(self, order_event: OrderEvent):
        if order_event.order_id == self._entry_order_id:
            if order_event.status == OrderStatus.FILLED and order_event.fill_quantity > 0:
                self._entry_price = order_event.fill_price
                self.debug(
                    f"Entry filled: {self._held_contract} at {self._entry_price:.2f}."
                )
                self._entry_order_id = None
            elif order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self.debug("Entry order did not fill.")
                self._entry_order_id = None
                if self._held_contract is not None and not self.portfolio[self._held_contract].invested:
                    self._held_contract = None
                    self._held_expiry = None
                    self._entry_price = None

        if order_event.order_id == self._exit_order_id:
            if order_event.status == OrderStatus.FILLED:
                self.debug(f"Exit filled: {self._held_contract}.")
                self._exit_order_id = None
                if self._held_contract is not None and not self.portfolio[self._held_contract].invested:
                    self._held_contract = None
                    self._held_expiry = None
                    self._entry_price = None
            elif order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self._exit_order_id = None

