        option.SetFilter(-100, 100, timedelta(0), timedelta(days=365))
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar

        self.current_slice = None
        self.held_symbol = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_price = None
        self.exit_reasons = {}
        self.no_entry_dates = set()

    def OnData(self, data: Slice):
        self.current_slice = data

        if self.Portfolio[self.spy].Invested:
            self.no_entry_dates.add(self.Time.date())
            if not self.HasOpenOrder(self.spy):
                self.Debug("Unexpected SPY exercise/assignment position; liquidating.")
                self.Liquidate(self.spy)

        self.ProcessExpiration()
        self.ProcessExits(data)

        if data.Bars.ContainsKey(self.spy):
            self.consolidator.Update(data.Bars[self.spy])

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if previous_ready else None
        previous_slow = self.slow.Current.Value if previous_ready else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not previous_ready or not (self.fast.IsReady and self.slow.IsReady):
            return

        if not (previous_fast <= previous_slow and
                self.fast.Current.Value > self.slow.Current.Value):
            return

        bar_time = bar.EndTime.time()
        if bar_time < time(9, 45) or bar_time > time(14, 30):
            return

        if self.Time.date() in self.no_entry_dates:
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            return

        if self.entry_order_id is not None:
            return

        self.TryEnter()

    def TryEnter(self):
        if self.current_slice is None:
            self.Debug("Entry skipped: no current Slice.")
            return

        if not self.current_slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Entry skipped: no SPY option chain.")
            return

        chain = self.current_slice.OptionChains[self.option_symbol]
        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Entry skipped: invalid SPY price.")
            return

        target_expiry = None
        for contract in chain:
            if contract.Right != OptionRight.Call:
                continue

            dte = (contract.Expiry.date() - self.Time.date()).days
            if dte == self.TARGET_DTE:
                target_expiry = contract.Expiry.date()
                break

        if target_expiry is None:
            self.Debug("Entry skipped: no expiration at target DTE.")
            return

        minimum_strike = spy_price * 1.01
        eligible = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == target_expiry
            and contract.Strike >= minimum_strike
        ]

        if not eligible:
            self.Debug("Entry skipped: no eligible call strike.")
            return

        selected = min(eligible, key=lambda c: (c.Strike, str(c.Symbol)))
        self.entry_order_id = self.MarketOrder(selected.Symbol, 1).OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol} strike {selected.Strike} "
            f"expiry {selected.Expiry.date()}"
        )

    def ProcessExits(self, data: Slice):
        if self.held_symbol is None:
            return

        if not self.Portfolio[self.held_symbol].Invested:
            if self.exit_order_id is None:
                self.held_symbol = None
                self.entry_price = None
            return

        if self.exit_order_id is not None:
            return

        if self.entry_price is None or self.entry_price <= 0:
            return

        if not data.QuoteBars.ContainsKey(self.held_symbol):
            return

        quote = data.QuoteBars[self.held_symbol]
        bid = quote.Bid.Close if quote.Bid is not None else 0
        ask = quote.Ask.Close if quote.Ask is not None else 0

        if bid > 0 and ask > 0:
            midpoint = (bid + ask) / 2
            if midpoint >= self.entry_price * 1.50:
                self.SubmitExit("profit target")

    def ProcessExpiration(self):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()

        if self.Time.date() >= expiry_date:
            self.no_entry_dates.add(self.Time.date())
            if self.Portfolio[self.held_symbol].Invested:
                self.SubmitExit("expiration protection")
            return

        if self.Time.hour == 15 and self.Time.minute == 45:
            prior_trading_day = self.PreviousTradingDay(expiry_date)
            if self.Time.date() == prior_trading_day:
                self.SubmitExit("pre-expiration time stop")

    def SubmitExit(self, reason):
        if self.held_symbol is None or not self.Portfolio[self.held_symbol].Invested:
            return

        if self.exit_order_id is not None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            self.Transactions.CancelOrder(order.Id)

        quantity = -self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_symbol, quantity)
        self.exit_order_id = ticket.OrderId
        self.exit_reasons[ticket.OrderId] = reason
        self.Debug(f"Exit submitted ({reason}): {self.held_symbol}")

    def PreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def HasOpenOrder(self, symbol):
        return len(self.Transactions.GetOpenOrders(symbol)) > 0

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {order_event.Symbol} at {order_event.FillPrice}"
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
                self.Debug(f"Entry canceled/invalid: {order_event.Symbol}")

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                reason = self.exit_reasons.pop(order_event.OrderId, "exit")
                self.Debug(
                    f"Exit filled ({reason}): {order_event.Symbol} "
                    f"at {order_event.FillPrice}"
                )
                self.exit_order_id = None
                self.held_symbol = None
                self.entry_price = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_reasons.pop(order_event.OrderId, None)
                self.exit_order_id = None
                self.Debug(f"Exit canceled/invalid: {order_event.Symbol}")

