        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(lambda universe: universe.Strikes(-100, 100).Expiration(0, 1000))
        self.option_symbol = option.Symbol

        self.closes = deque(maxlen=20)
        self.pending_entry_signal = False
        self.no_entry_date = None

        self.held_contract = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.equity_exit_ticket = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        previous_fast = None
        previous_slow = None

        if len(self.closes) == 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0

        self.closes.append(bar.Close)

        if previous_fast is None:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0
        bar_time = bar.EndTime.astimezone(self.TimeZone).time()

        if (previous_fast <= previous_slow and current_fast > current_slow
                and TimeSpan(9, 45, 0) <= bar_time <= TimeSpan(14, 30, 0)):
            self.pending_entry_signal = True

    def OnData(self, slice):
        today = self.Time.date()

        # Handle an unexpected exercise or assignment-created SPY position.
        if self.Portfolio[self.spy].Invested:
            if self.equity_exit_ticket is None or not self.equity_exit_ticket.Status.IsOpen():
                quantity = self.Portfolio[self.spy].Quantity
                self.equity_exit_ticket = self.MarketOrder(self.spy, -quantity)
                self.Debug(f"Unexpected SPY exercise/assignment position; liquidating {quantity} shares.")

        # Never intentionally hold an option into its expiration date.
        if self.held_contract is not None and self.Portfolio[self.held_contract].Invested:
            if self.held_contract.ID.Date.date() == today:
                self.no_entry_date = today
                self.SubmitExit("Expiration processing")
                return

        # Check held-call profit target on every minute Slice with a valid quote.
        if self.held_contract is not None and self.Portfolio[self.held_contract].Invested:
            self.CheckProfitTarget(slice)
            self.CheckTimeStop()

