        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry_signal = False

        self.entry_order_id = None
        self.exit_order_id = None
        self.equity_liquidation_order_id = None

        self.held_option = None
        self.entry_fill_price = None
        self.held_expiry_date = None
        self.no_entry_date = None

        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.five_minute_consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        prior_fast = self.previous_fast
        prior_slow = self.previous_slow

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if self.fast.IsReady and self.slow.IsReady:
            if (
                prior_fast is not None
                and prior_fast <= prior_slow
                and self.fast.Current.Value > self.slow.Current.Value
                and clock_time(9, 45) <= bar.EndTime.time() <= clock_time(14, 30)
            ):
                self.pending_entry_signal = True

            self.previous_fast = self.fast.Current.Value
            self.previous_slow = self.slow.Current.Value

    def OnData(self, data):
        today = self.Time.date()

        if self.Securities[self.spy].Holdings.Quantity != 0:
            self.HandleUnexpectedSpyHolding()
            self.pending_entry_signal = False
            return

        if self.held_option is not None:
            if today == self.held_expiry_date:
                self.no_entry_date = today
                self.SubmitOptionExit("expiration processing")
            else:
                self.CheckProfitTarget(data)
                if (
                    self.Time.time() == clock_time(15, 45)
                    and today == self.PreviousTradingDay(self.held_expiry_date)
                ):
                    self.SubmitOptionExit("15:45 pre-expiration time stop")

        if self.pending_entry_signal:
            self.pending_entry_signal = False

            if (
                self.held_option is None
                and self.entry_order_id is None
                and self.exit_order_id is None
                and self.no_entry_date != today
            ):
                self.TryEnter(data)

    def TryEnter(self, data):
        spy_bar = data.Bars.get(self.spy)
        spy_price = spy_bar.Close if spy_bar is not None else self.Securities[self.spy].Price

        if spy_price <= 0:
            self.Debug("Skipped entry: SPY price unavailable.")
            return

        contracts = []
        for chain in data.OptionChains.Values:
            for contract in chain:
                if (
                    contract.Right == OptionRight.Call
                    and (contract.Expiry.date() - self.Time.date()).days > 0
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no eligible call expiration in current chain.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in contracts)
        required_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= required_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying OTM call at selected expiration.")
            return

        selected = min(candidates, key=lambda c: (float(c.Strike), str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)

        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol} x1, expiry {selected_expiry}, "
            f"strike {selected.Strike}."
        )

    def CheckProfitTarget(self, data):
        if self.exit_order_id is not None or self.entry_fill_price is None:
            return

        midpoint = self.CurrentOptionMidpoint(data, self.held_option)
        if midpoint is not None and midpoint >= self.entry_fill_price * 1.50:
            self.SubmitOptionExit("50% profit target")

    def CurrentOptionMidpoint(self, data, symbol):
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol != symbol:
                    continue

                bid = float(contract.BidPrice)
                ask = float(contract.AskPrice)

                if bid > 0 and ask > 0:
                    return (bid + ask) / 2.0

                return None

        return None

    def SubmitOptionExit(self, reason):
        if self.held_option is None or self.exit_order_id is not None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_option):
            if order.Quantity < 0:
                self.Transactions.CancelOrder(order.Id, "Replacing option exit order")

        quantity = self.Securities[self.held_option].Holdings.Quantity
        if quantity <= 0:
            return

        ticket = self.MarketOrder(self.held_option, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted: {self.held_option}, reason: {reason}.")

    def HandleUnexpectedSpyHolding(self):
        if self.equity_liquidation_order_id is not None:
            return

        quantity = self.Securities[self.spy].Holdings.Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.spy, -quantity)
        self.equity_liquidation_order_id = ticket.OrderId
        self.Debug("Unexpected SPY exercise/assignment holding detected; liquidation submitted.")

    def PreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange = self.Securities[self.spy].Exchange

        while not exchange.DateIsOpen(datetime.combine(candidate, clock_time.min)):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, orderEvent):
        if orderEvent.OrderId == self.entry_order_id:
            if orderEvent.Status == OrderStatus.Filled:
                self.held_option = orderEvent.Symbol
                self.entry_fill_price = float(orderEvent.FillPrice)
                self.held_expiry_date = orderEvent.Symbol.ID.Date.date()
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_option} at {self.entry_fill_price:.2f}."
                )
            elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
                self.Debug(f"Entry order closed without fill: {orderEvent.Symbol}.")

        if orderEvent.OrderId == self.exit_order_id:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {orderEvent.Symbol} at {orderEvent.FillPrice:.2f}.")
                self.exit_order_id = None
                self.held_option = None
                self.entry_fill_price = None
                self.held_expiry_date = None
            elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

        if orderEvent.OrderId == self.equity_liquidation_order_id:
            if orderEvent.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.equity_liquidation_order_id = None

