        if self.held_contract is not None or self._entry_order_is_open():
            return

        if self.no_new_entries_today == self.Time.date():
            return

        bar_time = bar_end.time()
        if bar_time < datetime.strptime("09:45", "%H:%M").time():
            return
        if bar_time > datetime.strptime("14:30", "%H:%M").time():
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"Skipped entry at {self.Time}: no SPY option chain.")
            return

        spot = self.Securities[self.spy].Price
        if spot <= 0:
            self.Debug(f"Skipped entry at {self.Time}: invalid SPY price.")
            return

        # Use the nearest non-expired listed expiration, measured in calendar dates.
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call and
            (contract.Expiry.date() - self.Time.date()).days >= 1
        })

        if not expirations:
            self.Debug(f"Skipped entry at {self.Time}: no eligible expiration.")
            return

        expiry = expirations[0]
        minimum_strike = spot * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"Skipped entry at {self.Time}: no eligible call contract.")
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)

        if ticket is not None:
            self.entry_order_id = ticket.OrderId
            self.Debug(
                f"Entry submitted: {selected.Symbol}, expiry {expiry}, "
                f"strike {selected.Strike}."
            )

