        if self.held_contract is None:
            return

        holding = self.Portfolio[self.held_contract]
        if not holding.Invested:
            return

        quantity = holding.Quantity
        if quantity == 0 or self._exit_order_is_open():
            return

        contract = data.OptionChains.get(self.option_symbol)
        option_contract = None
        if contract is not None:
            for item in contract:
                if item.Symbol == self.held_contract:
                    option_contract = item
                    break

        if option_contract is not None:
            bid = option_contract.BidPrice
            ask = option_contract.AskPrice
            if bid > 0 and ask > 0 and self.entry_fill_price is not None:
                midpoint = (bid + ask) / 2.0
                if midpoint >= self.entry_fill_price * 1.50:
                    self._submit_exit("profit target")
                    return

        expiry = self.held_contract.ID.Date.date()
        if self.Time.date() == self._previous_trading_day(expiry):
            if self.Time.hour == 15 and self.Time.minute == 45:
                self._submit_exit("pre-expiration time stop")

    def _process_expiration_safety(self):
        if self.held_contract is None:
            return

        if not self.Portfolio[self.held_contract].Invested:
            return

        expiry = self.held_contract.ID.Date.date()
        if self.Time.date() >= expiry:
            self.no_new_entries_today = self.Time.date()
            if not self._exit_order_is_open():
                self._submit_exit("expiration safety")

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while not hours.IsDateOpen(candidate, False):
            candidate -= timedelta(days=1)

        return candidate

    def _submit_exit(self, reason: str):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        self.Transactions.CancelOpenOrders(self.held_contract)
        ticket = self.MarketOrder(self.held_contract, -quantity)

        if ticket is not None:
            self.exit_order_id = ticket.OrderId
            self.Debug(f"Exit submitted ({reason}): {self.held_contract}.")

    def _entry_order_is_open(self):
        if self.entry_order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(self.entry_order_id)
        if ticket is None:
            self.entry_order_id = None
            return False

        status = ticket.Status
        if status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
            self.entry_order_id = None
            return False

        return True

    def _exit_order_is_open(self):
        if self.exit_order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
        if ticket is None:
            self.exit_order_id = None
            return False

        status = ticket.Status
        if status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
            self.exit_order_id = None
            return False

        return True

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self.held_contract = order_event.Symbol
                self.entry_fill_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {order_event.Symbol} at "
                    f"{order_event.FillPrice:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at "
                    f"{order_event.FillPrice:.2f}."
                )
                if self.held_contract == order_event.Symbol:
                    self.held_contract = None
                    self.entry_fill_price = None
                self.exit_order_id = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

