        self.held_contract = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_fill_price = None
        self.expiration_date = None
        self.no_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        self.fast_closes.append(bar.Close)
        self.slow_closes.append(bar.Close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        fast = sum(self.fast_closes) / 5.0
        slow = sum(self.slow_closes) / 20.0

        if self.previous_fast is not None:
            bullish_cross = (
                self.previous_fast <= self.previous_slow and
                fast > slow
            )
            end_time = bar.EndTime
            if bullish_cross and (
                (end_time.hour, end_time.minute) >= (9, 45) and
                (end_time.hour, end_time.minute) <= (14, 30)
            ):
                self.pending_entry_time = end_time

        self.previous_fast = fast
        self.previous_slow = slow

    def OnData(self, data):
        today = self.Time.date()

        if self.no_entry_date != today:
            self.no_entry_date = None

        # Handle an unexpected equity position from exercise or assignment.
        if self.Portfolio[self.spy].Invested:
            self.Debug("Unexpected SPY exercise/assignment; liquidating SPY.")
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)

        # Do not intentionally carry an option into its expiration date.
        if (
            self.held_contract is not None and
            self.expiration_date is not None and
            today >= self.expiration_date
        ):
            self.no_entry_date = today
            if self.Portfolio[self.held_contract].Invested:
                self.Debug("Expiration processing; liquidating option.")
                self.SubmitExit("expiration")
            return

        self.EvaluateExit(data)

        # A signal must be acted on in the Slice that closed its five-minute bar.
        if self.pending_entry_time is not None:
            if self.pending_entry_time == self.Time:
                self.TryEnter(data)
            elif self.pending_entry_time < self.Time:
                self.pending_entry_time = None

    def TryEnter(self, data):
        signal_time = self.pending_entry_time
        self.pending_entry_time = None

        if self.no_entry_date == self.Time.date():
            return

        if (
            self.held_contract is not None or
            self.IsOpen(self.entry_ticket) or
            self.IsOpen(self.exit_ticket)
        ):
            return

        if not data.Bars.ContainsKey(self.spy):
            self.Debug("Entry skipped: no current SPY bar.")
            return

        spy_price = data.Bars[self.spy].Close
        if spy_price <= 0:
            self.Debug("Entry skipped: invalid SPY price.")
            return

        chain = self.GetSpyOptionChain(data)
        if chain is None:
            self.Debug("Entry skipped: no option chain.")
            return

        current_date = self.Time.date()
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain.Contracts.Values
            if contract.Right == OptionRight.Call and
               (contract.Expiry.date() - current_date).days > 0
        })

        if not expirations:
            self.Debug("Entry skipped: no eligible expiration.")
            return

        # Use the nearest available positive calendar-DTE expiration.
        selected_expiry = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain.Contracts.Values
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no eligible call strike.")
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.exit_ticket = None
        self.held_contract = None
        self.entry_fill_price = None
        self.expiration_date = selected.Expiry.date()
        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"expiry {selected_expiry} strike {selected.Strike}"
        )

    def EvaluateExit(self, data):
        if self.held_contract is None or not self.Portfolio[self.held_contract].Invested:
            return

        if self.expiration_date is not None:
            prior_trading_day = self.PreviousTradingDay(self.expiration_date)
            if (
                self.Time.date() == prior_trading_day and
                self.Time.hour == 15 and
                self.Time.minute == 45
            ):
                self.Debug("Exit submitted: pre-expiration time stop.")
                self.SubmitExit("time stop")
                return

        if self.entry_fill_price is None or self.entry_fill_price <= 0:
            return

        contract = self.FindHeldContract(data)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_fill_price:
            self.Debug("Exit submitted: 50% profit target.")
            self.SubmitExit("profit target")

    def SubmitExit(self, reason):
        if self.held_contract is None or not self.Portfolio[self.held_contract].Invested:
            return

        if self.IsOpen(self.exit_ticket):
