        )
        self.option_symbol = option.Symbol

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self._five_minute_bucket_end = None
        self._five_minute_close = None

        self.entry_order_id = None
        self.exit_order_ids = set()
        self.held_contract = None
        self.held_expiry = None
        self.entry_fill_price = None
        self.expiration_block_date = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self._check_time_stop
        )

    def OnData(self, data: Slice):
        today = self.Time.date()

        if self.held_contract is not None and today >= self.held_expiry:
            self.expiration_block_date = today
            self._submit_exit("expiration processing")

        if self.Securities[self.spy].Invested and self.held_contract is None:
            self.Debug(f"Unexpected SPY exercise/assignment position at {self.Time}; liquidating.")
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)

        self._check_profit_target(data)
        self._update_five_minute_bar(data)

    def _update_five_minute_bar(self, data: Slice):
        if self.spy not in data.Bars:
            return

        minute_bar = data.Bars[self.spy]
        end_time = minute_bar.EndTime

        regular_open = end_time.replace(hour=9, minute=30, second=0, microsecond=0)
        regular_close = end_time.replace(hour=16, minute=0, second=0, microsecond=0)

        if end_time <= regular_open or end_time > regular_close:
            return

        minutes_after_open = int((end_time - regular_open).total_seconds() / 60)
        bucket_number = (minutes_after_open - 1) // 5
        bucket_end = regular_open + timedelta(minutes=(bucket_number + 1) * 5)

        if self._five_minute_bucket_end is not None and bucket_end != self._five_minute_bucket_end:
            # The prior interval did not receive its closing minute bar, so discard it.
            self._five_minute_close = None

        self._five_minute_bucket_end = bucket_end
        self._five_minute_close = minute_bar.Close

        if end_time == bucket_end:
            close = self._five_minute_close
            self._five_minute_bucket_end = None
            self._five_minute_close = None
            self._on_completed_five_minute_bar(bucket_end, close, data)

    def _on_completed_five_minute_bar(self, bar_end: datetime, close: float, data: Slice):
        prior_fast = self.previous_fast
        prior_slow = self.previous_slow

        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        current_fast = sum(self.fast_closes) / 5.0
        current_slow = sum(self.slow_closes) / 20.0

        bullish_cross = (
            prior_fast is not None
            and prior_slow is not None
            and prior_fast <= prior_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not bullish_cross:
            return

        bar_time = bar_end.time()
        if bar_time < datetime.strptime("09:45", "%H:%M").time():
            return
        if bar_time > datetime.strptime("14:30", "%H:%M").time():
            return

        self._try_enter(data)

    def _try_enter(self, data: Slice):
        if self.expiration_block_date == self.Time.date():
            return
        if self.held_contract is not None or self.entry_order_id is not None:
            return
        if any(self._is_open_order(order_id) for order_id in self.exit_order_ids):
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug(f"Skipped call selection at {self.Time}: invalid SPY price.")
            return

        contracts = []
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue
                if contract.Expiry.date() <= self.Time.date():
                    continue
                contracts.append(contract)

        if not contracts:
            self.Debug(f"Skipped call selection at {self.Time}: no eligible option expiration.")
            return

        expiration = min(contract.Expiry.date() for contract in contracts)
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == expiration and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"Skipped call selection at {self.Time}: no call at least 1% OTM "
                f"for expiration {expiration}."
            )
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)

        if ticket is None or ticket.OrderId <= 0:
            self.Debug(f"Skipped call entry at {self.Time}: market order was not accepted.")
            return

        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol}, strike {selected.Strike}, "
            f"expiry {selected.Expiry.date()}."
        )

    def _check_profit_target(self, data: Slice):
        if self.held_contract is None or self.entry_fill_price is None:
            return
        if any(self._is_open_order(order_id) for order_id in self.exit_order_ids):
            return

        contract = self._find_contract_in_slice(data, self.held_contract)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self._submit_exit(
                f"50% profit target reached: midpoint {midpoint:.2f}, "
                f"entry {self.entry_fill_price:.2f}"
            )

    def _check_time_stop(self):
        if self.held_contract is None or self.held_expiry is None:
            return
        if any(self._is_open_order(order_id) for order_id in self.exit_order_ids):
            return

        exchange_hours = self.Securities[self.spy].Exchange.Hours
        prior_trading_day = exchange_hours.GetPreviousTradingDay(
            datetime.combine(self.held_expiry, datetime.min.time())
        ).date()

        if self.Time.date() == prior_trading_day:
            self._submit_exit("15:45 expiration-eve time stop")

    def _submit_exit(self, reason: str):
        if self.held_contract is None:
            return

        for order_id in list(self.exit_order_ids):
            if self._is_open_order(order_id):
                self.Transactions.GetOrderTicket(order_id).Cancel("Replacing open exit order")

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_contract, -quantity)
        if ticket is not None and ticket.OrderId > 0:
            self.exit_order_ids.add(ticket.OrderId)
            self.Debug(f"Exit submitted for {self.held_contract}: {reason}.")

    def _find_contract_in_slice(self, data: Slice, symbol: Symbol):
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _is_open_order(self, order_id: int) -> bool:
        ticket = self.Transactions.GetOrderTicket(order_id)
        if ticket is None:
            return False

        return ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        ]

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.held_expiry = order_event.Symbol.ID.Date.date()
                self.entry_fill_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_fill_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"Entry order {order_event.OrderId} did not fill.")
                self.entry_order_id = None

        if order_event.OrderId in self.exit_order_ids:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}.")
                self.exit_order_ids.discard(order_event.OrderId)
                self.held_contract = None
                self.held_expiry = None
                self.entry_fill_price = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_ids.discard(order_event.OrderId)

        if (
            order_event.Symbol == self.spy
            and self.Portfolio[self.spy].Invested
            and self.held_contract is None
        ):
            self.Debug(f"Unexpected SPY exercise/assignment event at {self.Time}; liquidating.")
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)

