        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        had_ready_averages = self.fast.IsReady and self.slow.IsReady
        prior_fast = self.fast.Current.Value if had_ready_averages else None
        prior_slow = self.slow.Current.Value if had_ready_averages else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not (had_ready_averages and self.fast.IsReady and self.slow.IsReady):
            return

        bullish_crossover = (
            prior_fast <= prior_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )
        self.previous_fast = self.fast.Current.Value
        self.previous_slow = self.slow.Current.Value

        if not bullish_crossover:
            return

        bar_time = bar.EndTime
        if not (
            (bar_time.hour == 9 and bar_time.minute >= 45)
            or 10 <= bar_time.hour <= 13
            or (bar_time.hour == 14 and bar_time.minute <= 30)
        ):
            return

        self.TryEnterFromCurrentSlice(bar.Close)

    def OnData(self, slice):
        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationProtection()
        self.HandleOptionExit(slice)

    def TryEnterFromCurrentSlice(self, spy_price):
        if self.Time.date() in self.expiration_blocked_dates:
            return

        if self.entry_order_id is not None or self.exit_order_id is not None:
            return

        if self.held_option is not None or self.Portfolio[self.option_symbol].Invested:
            return

        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chains = self.CurrentSlice.OptionChains
        if chains is None or not chains.ContainsKey(self.option_symbol):
            self.Debug("Skipped entry: no SPY option chain in current Slice.")
            return

        chain = chains[self.option_symbol]
        current_date = self.Time.date()

        contracts_by_expiry = {}
        for contract in chain:
            expiry_date = contract.Expiry.date()
            dte = (expiry_date - current_date).days
            if dte <= 0:
                continue

            if expiry_date not in contracts_by_expiry:
                contracts_by_expiry[expiry_date] = []
            contracts_by_expiry[expiry_date].append(contract)

        if not contracts_by_expiry:
            self.Debug("Skipped entry: no unexpired SPY option expiration available.")
            return

        selected_expiry = min(
            contracts_by_expiry.keys(),
            key=lambda expiry: (expiry - current_date).days
        )

        minimum_strike = spy_price * 1.01
        candidates = [
            contract for contract in contracts_by_expiry[selected_expiry]
            if contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"Skipped entry: no qualifying call at {selected_expiry}."
            )
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

