        if slice.QuoteBars is not None and slice.QuoteBars.ContainsKey(self.held_option):
            quote_bar = slice.QuoteBars[self.held_option]

        if quote_bar is None or quote_bar.Bid is None or quote_bar.Ask is None:
            return

        bid = quote_bar.Bid.Close
        ask = quote_bar.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self.SubmitOptionExit("50% profit target")

    def HandleExpirationProtection(self):
        if self.held_option is None or self.held_expiry_date is None:
            return

        if self.Time.date() >= self.held_expiry_date:
            self.expiration_blocked_dates.add(self.Time.date())
            if self.Portfolio[self.held_option].Quantity != 0:
                self.SubmitOptionExit("Expiration protection")

    def HandleUnexpectedSpyPosition(self):
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity == 0 or self.spy_liquidation_order_id is not None:
            return

        ticket = self.MarketOrder(
            self.spy,
            -spy_quantity,
            tag="Unexpected exercise/assignment cleanup"
        )
        self.spy_liquidation_order_id = ticket.OrderId
        self.Debug("Unexpected SPY position detected; liquidation submitted.")

    def SubmitOptionExit(self, reason):
        if self.held_option is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_option):
            self.Transactions.CancelOrder(order.Id, reason)

        ticket = self.MarketOrder(self.held_option, -quantity, tag=reason)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted: {reason} for {self.held_option}.")

    def PreviousSpyTradingDay(self, expiration_date):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        return exchange_hours.GetPreviousTradingDay(expiration_date).date()

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.held_expiry_date = order_event.Symbol.ID.Date.date()
                self.entry_fill_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_option} at "
                    f"{self.entry_fill_price:.2f}."
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.entry_order_id = None
                self.Debug("Entry order canceled or invalid.")

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at "
                    f"{order_event.FillPrice:.2f}."
                )
                self.exit_order_id = None
                self.held_option = None
                self.held_expiry_date = None
                self.entry_fill_price = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None
                self.Debug("Exit order canceled or invalid.")

        if order_event.OrderId == self.spy_liquidation_order_id:
            if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
                self.spy_liquidation_order_id = None

