from AlgorithmImports import *
from datetime import datetime, timedelta


class FiveMinuteSpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            False,
            0,
            False
        ).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_exchange_hours = self.Securities[self.spy].Exchange.Hours

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe.Strikes(-100, 100).Expiration(
                timedelta(days=0), timedelta(days=365)
            )
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

        self.held_contract = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_fill_price = None
        self.no_entry_date = None
        self.equity_liquidation_pending = False

    def OnFiveMinuteBar(self, sender, bar):
        previous_fast_ready = self.fast.IsReady
        previous_slow_ready = self.slow.IsReady
        previous_fast = self.fast.Current.Value
        previous_slow = self.slow.Current.Value

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not (previous_fast_ready and previous_slow_ready):
            return

        bullish_crossover = (
            previous_fast <= previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        end_time = bar.EndTime
        eligible_time = (
            (end_time.hour > 9 or (end_time.hour == 9 and end_time.minute >= 45)) and
            (end_time.hour < 14 or (end_time.hour == 14 and end_time.minute <= 30))
        )

        if bullish_crossover and eligible_time:
            self.TryEnterCall()

    def TryEnterCall(self):
        current_date = self.Time.date()

        if self.no_entry_date == current_date:
            return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Quantity != 0:
            return

        if self.entry_order_id is not None:
            return

        if self.entry_order_id is None and self.held_contract is not None:
            self.held_contract = None
            self.entry_fill_price = None

        chain = self.CurrentSlice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Entry skipped: no SPY option chain in current Slice.")
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Entry skipped: SPY has no valid current price.")
            return

        calls = [
            contract for contract in chain
            if contract.Right == OptionRight.Call and
            contract.Expiry.date() > current_date
        ]

        if not calls:
            self.Debug("Entry skipped: no non-expired SPY calls available.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in calls)
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in calls
            if contract.Expiry.date() == selected_expiry and
            contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call at the selected expiration.")
            return

        contract = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        ticket = self.MarketOrder(contract.Symbol, 1)

        if ticket is not None:
            self.entry_order_id = ticket.OrderId
            self.Debug(
                "Entry submitted: {0}, expiry {1}, strike {2}."
                .format(contract.Symbol, contract.Expiry.date(), contract.Strike)
            )

    def OnData(self, data):
        self.HandleUnexpectedSpyPosition()

        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            self.held_contract = None
            self.entry_fill_price = None
            self.exit_order_id = None
            return

        expiry = self.held_contract.ID.Date.date()
