from AlgorithmImports import *
from datetime import time


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        self.OptionFilterUniverse = self.option_symbol
        self.SetSecurityInitializer(
            BrokerageModelSecurityInitializer(
                self.BrokerageModel,
                FuncSecuritySeeder(self.GetLastKnownPrices)
            )
        )

        self.Securities[self.option_symbol].SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )

        self.close_window = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry_signal = False

        self.held_contract = None
        self.entry_order_id = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_order_id = None
        self.equity_liquidation_order_id = None
        self.blocked_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        self.close_window.Add(float(bar.Close))

        if not self.close_window.IsReady:
            return

        closes = list(self.close_window)
        fast = sum(closes[:5]) / 5.0
        slow = sum(closes[:20]) / 20.0

        crossover = (
            self.previous_fast is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_time = bar.EndTime.time()
        if crossover and time(9, 45) <= bar_time <= time(14, 30):
            self.pending_entry_signal = True

    def OnData(self, data):
        self.HandleUnexpectedEquityPosition()
        self.HandleExpirationProcessing()
        self.HandleOpenOptionExit(data)

        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self.TryEnter(data)

    def TryEnter(self, data):
        if self.blocked_entry_date == self.Time.date():
            return

        if self.entry_order_id is not None or self.exit_order_id is not None:
            return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Quantity != 0:
            return

        chain = None
        for candidate_chain in data.OptionChains.Values:
            if candidate_chain.Symbol == self.option_symbol:
                chain = candidate_chain
                break

        if chain is None:
            self.Debug(f"{self.Time}: Entry skipped: no SPY option chain.")
            return

        current_spy_price = self.Securities[self.spy].Price
        if current_spy_price <= 0:
            self.Debug(f"{self.Time}: Entry skipped: invalid SPY price.")
            return

        calls = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and (contract.Expiry.date() - self.Time.date()).days >= 1
        ]

        if not calls:
            self.Debug(f"{self.Time}: Entry skipped: no eligible call expiration.")
            return

        expirations = sorted({
            contract.Expiry.date() for contract in calls
        })

        selected_expiry = expirations[0]
        minimum_strike = current_spy_price * 1.01

        eligible_contracts = [
            contract for contract in calls
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not eligible_contracts:
            self.Debug(
                f"{self.Time}: Entry skipped: no call at least 1% OTM for "
                f"{selected_expiry}."
            )
            return

        selected = min(
            eligible_contracts,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.entry_symbol = selected.Symbol
        self.Debug(
            f"{self.Time}: Submitted entry for 1 {selected.Symbol} "
            f"(strike {selected.Strike}, expiry {selected.Expiry.date()})."
        )

    def HandleOpenOptionExit(self, data):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        expiry = self.held_contract.ID.Date
        previous_trading_day = (
            self.Securities[self.spy].Exchange.Hours
            .GetPreviousTradingDay(expiry)
            .date()
        )

        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() == time(15, 45)
        ):
            self.SubmitExit("expiration time stop")
            return

        if self.entry_price is None or self.exit_order_id is not None:
            return

        contract = self.GetContractFromSlice(data, self.held_contract)
        if contract is None or contract.BidPrice <= 0 or contract.AskPrice <= 0:
            return

        midpoint = (contract.BidPrice + contract.AskPrice) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.SubmitExit(
                f"profit target reached at midpoint {midpoint:.2f}"
            )

    def HandleExpirationProcessing(self):
        if self.held_contract is None:
            return

        if (
            self.Portfolio[self.held_contract].Quantity != 0
            and self.Time.date() >= self.held_contract.ID.Date.date()
        ):
            self.blocked_entry_date = self.Time.date()
            self.SubmitExit("expiration processing")

    def SubmitExit(self, reason):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0 or self.exit_order_id is not None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id, "Replacing with option exit")

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: Submitted exit for {self.held_contract}: {reason}.")

    def GetContractFromSlice(self, data, symbol):
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def HandleUnexpectedEquityPosition(self):
        equity_quantity = self.Portfolio[self.spy].Quantity
        if equity_quantity == 0 or self.equity_liquidation_order_id is not None:
            return

        ticket = self.MarketOrder(self.spy, -equity_quantity)
        self.equity_liquidation_order_id = ticket.OrderId
        self.blocked_entry_date = self.Time.date()
        self.Debug(
            f"{self.Time}: Unexpected SPY position from exercise/assignment; "
            f"submitted liquidation for {equity_quantity} shares."
        )

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_order_id == order_event.OrderId
                and order_event.Symbol == self.entry_symbol
                and order_event.Direction == OrderDirection.Buy
            ):
                self.held_contract = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None
                self.entry_symbol = None
                self.Debug(
                    f"{self.Time}: Entry filled for {self.held_contract} "
                    f"at {self.entry_price:.2f}."
                )

            elif (
                self.exit_order_id == order_event.OrderId
                and self.held_contract == order_event.Symbol
            ):
                self.Debug(
                    f"{self.Time}: Exit filled for {self.held_contract} "
                    f"at {order_event.FillPrice:.2f}."
                )
                self.held_contract = None
                self.entry_price = None
                self.exit_order_id = None

            elif self.equity_liquidation_order_id == order_event.OrderId:
                self.equity_liquidation_order_id = None

        elif order_event.Status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.None
        ):
            if order_event.OrderId == self.entry_order_id:
                self.entry_order_id = None
                self.entry_symbol = None

            if order_event.OrderId == self.exit_order_id:
                self.exit_order_id = None

            if order_event.OrderId == self.equity_liquidation_order_id:
                self.equity_liquidation_order_id = None

